document.addEventListener("DOMContentLoaded", () => {
Promise.all([import("./crew-member.js"), import("./commander.js")]).then(([member, commander]) => {
    const vega = new commander.default({ name: "Vega", role: "Commander" });
    const lyra = new member.default({ name: "Lyra", role: "Engineer" });
    console.log("test: " + (vega instanceof member.default ? "a commander is a crew member" : "a commander is something else"));
    console.log("test: " + vega.describe() + " is in charge: " + vega.isInCharge());
    console.log("test: " + lyra.describe() + " is in charge: " + lyra.isInCharge());
  })
  .catch((error) => console.log("test: failed " + error.message));
});
